# AI-GENERATED FILE: written by Claude (Anthropic), not hand-written by the developer.
"""Version consistency across the four places a version lives (KR-017).

``APWORLD_VERSION`` reaches the client through slot data and picks the communication agent;
``world_version`` in ``archipelago.json`` is what Archipelago shows to players; and the patcher
carries ``apworld_to_mod_map`` plus ``min_apworld``. Nothing in the code keeps them in step, so
this is where a half-finished version bump is caught.
"""

from __future__ import annotations

import json
import unittest
from pathlib import Path

from ... import APWORLD_VERSION, GAME_FULL_NAME, KhimeraDAMGWorld
from ...client.patcher import _get_mod_version, apworld_to_mod_map, max_apworld, min_apworld
from ...patches import patch_map

WORLD_ROOT = Path(__file__).resolve().parents[2]
MANIFEST_PATH = WORLD_ROOT / "archipelago.json"
INCLUDE_PATH = WORLD_ROOT / "patches" / "include.txt"


def version_tuple(version: str) -> tuple[int, ...]:
    return tuple(int(part) for part in version.split("."))


class TestManifest(unittest.TestCase):
    """``archipelago.json`` is the author-owned half of the manifest."""

    @classmethod
    def setUpClass(cls) -> None:
        cls.manifest = json.loads(MANIFEST_PATH.read_text(encoding="utf-8"))

    def test_fields(self) -> None:
        self.assertEqual(
            set(self.manifest),
            {"game", "authors", "minimum_ap_version", "world_version"},
            f"{MANIFEST_PATH.name} holds {sorted(self.manifest)}"
        )

    def test_build_generated_fields_are_absent(self) -> None:
        # The build component writes "version" and "compatible_version" into the packaged
        # manifest. Writing them here makes the packaged file unreadable.
        for field in ("version", "compatible_version"):
            self.assertNotIn(
                field,
                self.manifest,
                f"\"{field}\" must be left to the Build APWorlds component"
            )

    def test_game_name_matches_the_world(self) -> None:
        self.assertEqual(
            self.manifest["game"],
            GAME_FULL_NAME,
            "the manifest game name has to match the world class, and a player YAML, exactly"
        )
        self.assertEqual(KhimeraDAMGWorld.game, GAME_FULL_NAME)

    def test_world_version_matches_the_module(self) -> None:
        self.assertEqual(
            self.manifest["world_version"],
            APWORLD_VERSION,
            f"archipelago.json says {self.manifest['world_version']} but __init__.py says {APWORLD_VERSION}; "
            "the first is shown to players, the second is what the client receives"
        )

    def test_required_client_version_is_not_below_the_minimum_core(self) -> None:
        minimum = version_tuple(self.manifest["minimum_ap_version"])
        self.assertGreaterEqual(
            tuple(KhimeraDAMGWorld.required_client_version),
            minimum,
            f"required_client_version {KhimeraDAMGWorld.required_client_version} is older than the "
            f"declared minimum core {self.manifest['minimum_ap_version']}"
        )


class TestPatcherVersionTables(unittest.TestCase):
    """The patcher's two version tables have to cover the running version."""

    def test_the_current_version_has_a_mod_mapping(self) -> None:
        digits = version_tuple(APWORLD_VERSION)
        self.assertIn(
            digits,
            apworld_to_mod_map,
            f"apworld_to_mod_map has no entry for {APWORLD_VERSION}; the client would refuse to launch "
            "games for its own version"
        )

    def test_the_current_version_is_the_newest_mapping(self) -> None:
        self.assertEqual(
            version_tuple(APWORLD_VERSION),
            max_apworld,
            f"the newest mapped version is {max_apworld} but the world is {APWORLD_VERSION}"
        )

    def test_the_current_version_is_not_below_the_floor(self) -> None:
        self.assertGreaterEqual(
            version_tuple(APWORLD_VERSION),
            min_apworld,
            f"min_apworld is {min_apworld}, which is above the world's own version {APWORLD_VERSION}"
        )

    def test_the_mapped_mod_release_is_packaged(self) -> None:
        mod_version = _get_mod_version(APWORLD_VERSION)
        mod_version_text = ".".join(str(part) for part in mod_version)
        included = [line.strip() for line in INCLUDE_PATH.read_text(encoding="utf-8").splitlines() if line.strip()]
        self.assertIn(
            mod_version_text,
            included,
            f"mod release {mod_version_text} is what this apworld version maps to, but "
            f"patches/include.txt lists {included}; the build would not package its patches"
        )

    @unittest.skipUnless(patch_map, "patches/data.py is generated by the build")
    def test_the_mapped_mod_release_has_patches(self) -> None:
        mod_version = _get_mod_version(APWORLD_VERSION)
        for_version = [build for (version, build) in patch_map if version == mod_version]
        self.assertTrue(
            for_version,
            f"the build tables hold no patches for mod release {mod_version}"
        )
